import { createPoseLibrary, samplePose, compose, multiply, transform, consumesRootTranslation } from '../../tools/assets/character/sample_pose.mjs';

// Expected deformation: decoded source KAC pose + GLB inverse-bind/vertex bytes.
// Observed deformation: the actual Babylon shader bone palette + mesh world.
// No palette, transformed vertex, or expectation is generated by the player.
export function createSkinAudit(sourceDocument, glb) {
  const library = createPoseLibrary(sourceDocument), { json, accessor } = glb;
  const geometry = json.nodes.filter(n => n.skin !== undefined).flatMap(n => {
    const skin = json.skins[n.skin], primitives = json.meshes[n.mesh].primitives;
    return primitives.map((primitive,index) => ({ name: primitives.length > 1 ? n.name+'_primitive'+index : n.name, offsets: accessor(skin.inverseBindMatrices),
      jointNames: skin.joints.map(j => json.nodes[j].name),
      vertices: accessor(primitive.attributes.POSITION), joints: accessor(primitive.attributes.JOINTS_0), weights: accessor(primitive.attributes.WEIGHTS_0) }));
  });
  const parents = new Map(); json.nodes.forEach((n, i) => (n.children || []).forEach(child => parents.set(child, i)));
  const rigid = json.nodes.flatMap((n, i) => n.mesh !== undefined && n.skin === undefined ? json.meshes[n.mesh].primitives.map((primitive,index,primitives) => ({ index: i,
    name: primitives.length > 1 ? n.name+'_primitive'+index : n.name, vertices: accessor(primitive.attributes.POSITION) })) : []);
  function reflect(matrix, scale) { return matrix.map((v, index) => v * (index % 4 === 2 ? -1 : 1) * (Math.floor(index / 4) === 2 ? -1 : 1) * (index % 4 < 3 ? scale : 1)); }
  return (view, actor, scale = .01) => {
    const native = samplePose(library, view.sample.name, view.sample.seconds, {
      transition:view.sample.transition?{clipName:view.sample.transition.fromName,timeSeconds:view.sample.transition.oldSeconds,weight:view.sample.transition.weight}:null,
      rootTranslationOverride: consumesRootTranslation(actor) ? [0, null, 0] : null,
      worldMatrix: compose([actor.x, actor.y, actor.z], [1, 1, 1], actor.facing < 0 ? [0, 1, 0, 0] : [0, 0, 0, 1]),
    });
    let maximumErrorNative = 0, vertices = 0, worst = null;
    for (const g of geometry) {
      const mesh = view.meshes.find(m => m.name === view.id + '_' + g.name);
      if (!mesh?.skeleton) throw Error('Missing actual skin: ' + g.name);
      const palette = mesh.skeleton.getTransformMatrices(mesh), world = mesh.getWorldMatrix().asArray();
      const expectedMatrices = g.jointNames.map((name, i) => {
        const matrix = native.get(name); if (!matrix) throw Error('Missing source skin joint: ' + name);
        const reflected = reflect(matrix, scale);
        return multiply(reflected, g.offsets[i]);
      });
      for (const fraction of [0, .2, .4, .6, .8, 1]) {
        const index = Math.floor((g.vertices.length - 1) * fraction), actualLocal = [0, 0, 0], expected = [0, 0, 0];
        for (let joint = 0; joint < 4; joint++) {
          const weight = g.weights[index][joint]; if (!weight) continue;
          const id = g.joints[index][joint];
          const a = transform(palette.slice(id * 16, (id + 1) * 16), g.vertices[index]);
          const b = transform(expectedMatrices[id], g.vertices[index]);
          for (let axis = 0; axis < 3; axis++) { actualLocal[axis] += a[axis] * weight; expected[axis] += b[axis] * weight; }
        }
        const actual = transform(world, actualLocal);
        for (let axis = 0; axis < 3; axis++) {
          const error = Math.abs(actual[axis] - expected[axis]) / scale;
          if(error > maximumErrorNative) { maximumErrorNative = error; worst = { mesh: g.name, index, axis, actual, expected, weights: g.weights[index], joints: g.joints[index] }; }
        }
        vertices++;
      }
    }
    // The sword is rigid geometry attached to the animated source right hand.
    function rigidWorld(index) {
      const node = json.nodes[index], source = native.get(node.name);
      if (source) return reflect(source, scale);
      const local = node.matrix || compose(node.translation || [0, 0, 0], node.scale || [1, 1, 1], node.rotation || [0, 0, 0, 1]);
      const parent = parents.get(index);
      if (parent === undefined) throw Error('Rigid asset has no source bone ancestor: ' + node.name);
      return multiply(rigidWorld(parent), local);
    }
    for (const g of rigid) {
      const mesh = view.meshes.find(m => m.name === view.id + '_' + g.name);
      if (!mesh) throw Error('Missing rigid weapon: ' + g.name);
      const actualMatrix = mesh.getWorldMatrix().asArray(), expectedMatrix = rigidWorld(g.index);
      for (const fraction of [0, .2, .4, .6, .8, 1]) {
        const point = g.vertices[Math.floor((g.vertices.length - 1) * fraction)];
        const actual = transform(actualMatrix, point), expected = transform(expectedMatrix, point);
        for (let axis = 0; axis < 3; axis++) maximumErrorNative = Math.max(maximumErrorNative, Math.abs(actual[axis] - expected[axis]) / scale);
        vertices++;
      }
    }
    return { vertices, maximumErrorNative, worst };
  };
}
